sp_widget.client_script:
function($scope, $rootScope, $timeout) {
  var c = this;

  c.selectedYear = "";

  function atualizarIndicador() { // Renomeado para refletir o foco em um indicador
    c.server.get({ selectedYear: c.selectedYear }).then(function(response) {
      c.data = response.data;
      console.log("Indicador PAF atualizado:", c.selectedYear, c.data);
    });
  }

  // Recebe o ano vindo de outro widget
  $rootScope.$on('anoSelecionado', function(event, ano) {
    c.selectedYear = ano;
    atualizarIndicador();
  });

  // Primeira carga
  atualizarIndicador();
}

sp_widget.css:
.financial-widget {
  border: 1px solid #ccc;
  border-radius: 4px;
  overflow: hidden;
  margin-top: 4rem;
}

.indicator-block {
  text-align: center;
  padding: 0;
}

.indicator-header {
  background-color: #EBEDF1;
  color: #021770;
  font-weight: 400;
  padding: 8px 10px;
  font-size: 14px;
  border-bottom: 1px solid #C7C7C7;
}

.indicator-value {
  color: #021770;
  font-size: 32px;
  font-weight: 400;
  padding: 10px 10px 15px;
}

sp_widget.script:
(function() {

  input = input || {};
  var table = 'x_sded9_portal_t_0_programa_de_ajuste_fiscal';

  var selectedYear = input.selectedYear || "";

  // Se nenhum ano vier, pega o mais recente
  if (!selectedYear) {
    var g = new GlideRecord(table);
    g.orderByDesc('u_ano');
    g.setLimit(1);
    g.query();
    if (g.next())
      selectedYear = g.getValue('u_ano');
  }

  data.selectedYear = selectedYear;

  data.indicator = { // Renomeado para 'indicator' e contem apenas o endividamento
    valorApurado: { value: '0%', label: 'Valor Apurado: ' + selectedYear }
  };

  var gr = new GlideRecord(table);

  if (selectedYear)
    gr.addQuery('u_ano', selectedYear);

  gr.orderByDesc('sys_created_on');
  gr.setLimit(1);
  gr.query();

  if (gr.next()) {
    var anoReal = gr.getValue('u_ano');
    
    // CORREÇÃO: Acessando o valor da coluna usando o nome correto da coluna (troque 'u_valor_apurado_endividamento' pelo seu campo)
    var valorEndividamento = gr.getValue('u_valor_apurado_endividamento');
    
    // Verifica se o valor existe antes de anexar '%'
    if (valorEndividamento) {
      data.indicator.valorApurado.value = valorEndividamento + '%';
    } else {
      data.indicator.valorApurado.value = 'N/A';
    }
    
    data.indicator.valorApurado.label = 'Valor Apurado: ' + anoReal;
    
    data.selectedYear = anoReal;
  }

})();
